square(n: int) -> int {
    return n * n
}

main() {
    for i in 1..5 {
        println("${i} -> ${square(i)}")
    }
}

message Inc { n: int }

actor Counter {
    state count = 0
    receive {
        Inc(n) -> {
            count = count + n
            println("count = ${count}")
        }
    }
}

main() {
    c = spawn(Counter())
    c ! Inc { n: 41 }
    c ! Inc { n: 1 }
}

safe_divide(a: int, b: int) -> {
    if b == 0 {
        return 0, "division by zero"
    }
    return a / b, ""
}

main() {
    q, err = safe_divide(42, 6)
    if err != "" {
        println("error: ${err}")
        return
    }
    println("42 / 6 = ${q}")

    _, err2 = safe_divide(1, 0)
    println("1 / 0 -> ${err2}")
}

